// th15_s1_b3 — TH15 v1.00b Stage 1 关底 Boss 第3攻击
// 源: st01bs.ecl.txt Boss2 (231-295); 依赖 Boss2_at (297-339), Boss2_at2 (341-406)
// 入口状态取自 st01bs.ecl.txt Boss (8-47): 位置(0,128)、受击框40/体碰框48、限位共用。
// 卡帧0=入口; 开场120帧缓冲后由 pattern 创建真实 Boss; 源 t=0 对应真实 Boss 主任务首帧。

const TIME_LIMIT: int = 2224;
const OPENING_BUFFER: int = 120;

// TH15 type13 复用现代目录同值槽 (TH15_BULLET 半径2.39999); 颜色单独传。
const TH15_BULLET: int = 560;
const COLOR_AT: int = 8;   // Boss2_at  etSprite(0,13,8)
const COLOR_AT2: int = 6;  // Boss2_at2 etSprite(1,13,6)

// ---------------------------------------------------------------------------
// moveRand(60,4,1.0) + moveLimit(0,128,280,96)
// 方向内区 x∈[-70,70], y∈[104,152] (中心±宽高/4); 实际限位 x∈[-140,140], y∈[80,176]。
// 速度 v(k)=1-k/60, k=1..60。共享 int0=步计数, fx0/fx1=cos/sin。
// ---------------------------------------------------------------------------
sub mr_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var spd: fx = 0fx;
    if k < 60 { spd = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * spd;
    var ny: fx = $self_y + self_fx(1) * spd;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub mr_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mr_arm_next();
}
sub mr_move_rand() {
    // R = pi*U_signed, 以未回绕 BAM int 计算。
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = 0 - a; }
    } else if $self_y > 152fx {
        if a < 0 { a = 0 - a; }
        a = 0 - a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mr_begin(a as angle);
}
sub mr_wait(n: int) {
    for i in 0..n {
        wait(1);
        mr_arm_next();
    }
}

// ---------------------------------------------------------------------------
// Boss2_at: 自机狙扇形, 每波路数 1,2,...,G; 每 6 帧一发。
// 源 etAngle(ANGLE_PLAYER, 0.034906585) 只设一次 => 一波内基准角固定, 路间距2°。
// 速度(E/N/H/L)=1.5/2.5/3.5/3.5; G=6/10/14/14。
// 退位移: 无 etDist, ANIM 进入 position-=4*velocity => 出生点后移 4*speed。
// ---------------------------------------------------------------------------
async sub at_task() {
    var speed: fx = 1.5fx;
    var g: int = 6;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { speed = 2.5fx; g = 10; }
    else if rank == RANK_HARD { speed = 3.5fx; g = 14; }
    else if rank == RANK_LUNATIC { speed = 3.5fx; g = 14; }
    var base: angle = aim_player();
    var back: fx = 0fx - 4fx * speed;
    var delta: int = 2deg as int;
    var f: int = 1;
    for burst in 0..g {
        // 源 mode1 fan: 路 i 相对中轴偏移 F(N,i), 保序。
        for i in 0..f {
            var off: int = ((i + 1) / 2) * delta;
            if f % 2 == 0 { off = (i / 2) * delta + delta / 2; }
            if i % 2 != 0 { off = 0 - off; }
            var a: angle = base + (off as angle);
            var px: fx = $self_x + back * cos(a);
            var py: fx = $self_y + back * sin(a);
            _ = fire(TH15_BULLET, COLOR_AT, px, py, speed, a, none, none);
        }
        f = f + 1;
        wait(6);
    }
}

// ---------------------------------------------------------------------------
// Boss2_at2: 每发以 RANDRAD 为基角发同心环。
// 路数/层/首速 (E/N/H/L): 10/5/1, 10/5/1, 16/10/3, 25/10/4; 末速0.8。
// 每发 etAngle(RANDRAD,0) 会把层偏角清零 (源初设2°被覆盖) => 层间只差速度。
// etDist=64, ANIM 退位移 => 每层出生半径 64-4*v(q)。
// 发数600, 间隔 E=110 其余90。
// ---------------------------------------------------------------------------
async sub at2_task() {
    var rank: int = global(GVAR_RANK);
    var lanes: int = 10;
    var layers: int = 5;
    var spd0: fx = 1fx;
    if rank == RANK_HARD { lanes = 16; layers = 10; spd0 = 3fx; }
    else if rank == RANK_LUNATIC { lanes = 25; layers = 10; spd0 = 4fx; }
    var spd_step: fx = (0.8fx - spd0) / (layers - 1);
    wait(100);
    sh_reset(0);
    sh_sprite(0, TH15_BULLET, COLOR_AT2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    var shots: int = 600;
    var gap: int = 90;
    if rank == RANK_EASY { gap = 110; }
    loop {
        var base: angle = (rand(65536) - 32768) as angle;
        for q in 0..layers {
            var v: fx = spd0 + spd_step * (q as fx);
            var dist: fx = 64fx - 4fx * v;
            sh_angle(0, base, 0deg);
            sh_speed(0, v, 0fx);
            sh_dist(0, dist);
            sh_count(0, lanes, 1);
            sh_fire(0);
        }
        shots = shots - 1;
        if shots <= 0 { return; }
        wait(gap);
    }
}

// ---------------------------------------------------------------------------
// 真实 Boss: 源 Boss2 主任务。入口清弹/章节/掉落/音效/ANM/lifeMarker/
// setInterrupt 等按合成外壳与公共口径省略; 保留首发等待、两路并发发射与 moveRand。
// ---------------------------------------------------------------------------
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);   // 源 setHitbox(48,48) -> 半径24
    set_hurtbox(20fx);  // 源 setHurtbox(40,40) -> 半径20
    set_self_int(0, 0);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    // 源 t=0..4 前奏(两个+2) + timerReset 后 wait(90) => 首发在源 t=94。
    wait(94);
    spawn at2_task();
    loop {
        spawn at_task();
        mr_wait(60);
        mr_move_rand();
        mr_wait(80);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 11400, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
